window.__BUNDLE__={"generatedAt":"2026-10-24T21:10:55.263071+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-10-17","archiveCutoff":"2021-10-25","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":350,"arxiv":1408,"total":1758},"freshness":{"latestPaperDate":"2026-10-23","latestPublishedDate":"2026-10-23","latestBatchCount":311,"newInLast24h":0,"newInLast48h":353},"historyTotal":27019,"topicCounts":{"Multi-Agent":2955,"Evaluation":14774,"Planning":1999,"Memory":529,"Code Agent":1070,"Interpretability":914,"Agentic RAG":1479,"Agentic Search":1967,"RL for LLM":1461,"Reasoning":7325,"Hallucination":1222,"Post-Training":3060,"Alignment":3557,"World Model":534,"Tool Use":1415,"Agent Safety":2657,"Computer Use":363,"Reflection":969,"VLM Training":2099,"LLM Training":3447,"Fine-tuning":4169,"Multimodal Agent":156,"Agent Framework":924,"Error Attribution":173,"Data Engine":541},"count":36,"recentTotal":2152,"archiveCount":0,"archiveTotal":24867,"sources":{"hf":63,"arxiv":2089,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"hfUrl":"https://huggingface.co/papers/2610.30181","url":"https://arxiv.org/abs/2610.30181","pdf":"https://arxiv.org/pdf/2610.30181.pdf","id":"arxiv:2610.30181","announceDate":"2026-10-23","tags":["Agentic Search","Evaluation"],"source":"hf","submittedDate":"2026-10-19","arxiv":"https://arxiv.org/abs/2610.30181","topics":["Agentic Search","Evaluation"],"authors":["Xiaomin Yu","Hongliang Chen","Zhe Huang","Shilin Yan","Shao-Rong Su","Xuqiao Ma","Feiyang Wang","Jiayu Chen","Jiwei Fang","Yu Yan","Yini Huang","Chen Chen","Ruoxi Cheng","Yuzhi He","Yuhui Zhang","Xiaoxing Hu","Chen Liu","Jianbo Lin","Yijiang Li","Xiaobin Hu","Menglong Li","Zhuoran Lu","Weishi Wang","Zhongqi Yue","Chengwei Qin"],"title":"Deep Search in Real-World Web Environments","date":"2026-10-23","upvotes":154,"abstract":"Despite substantial progress in Deep Search agents, their ability to conduct end-to-end research in real-world open Web environments remains insufficiently evaluated. Unlike static retrieval settings, information on the real-world Web is distributed across diverse sources, modalities, and heterogeneous formats, often involving complex interaction mechanisms that require agents to autonomously search for, access, and integrate relevant evidence during execution. To address this gap, we introduce the OpenDS task, designed to evaluate agents' ability to perform multi-step deep search in the live, open Web. This task requires agents to autonomously explore the real Web, discover and connect relevant evidence from multiple independent sources through Web search, browser interaction, and evidence processing, and ultimately determine a unique factual answer. Building on this task formulation, w"},{"hfUrl":"https://huggingface.co/papers/2610.31158","url":"https://arxiv.org/abs/2610.31158","pdf":"https://arxiv.org/pdf/2610.31158.pdf","id":"arxiv:2610.31158","announceDate":"2026-10-23","tags":["Agentic Search","Evaluation"],"source":"hf","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31158","topics":["Agentic Search","Evaluation"],"authors":["Jiahao Meng","Qize Yang","Yuxuan Wang","Yunfei Chu","Wensi Dai","Jin Xu","Yunhai Tong"],"title":"Beyond Watching and Searching: Benchmarking Agents for Video-centered Deep Research Reports","date":"2026-10-23","upvotes":17,"abstract":"Deep research agents synthesize open-web evidence into long reports, but current benchmarks do not evaluate research centered on a source video. We introduce Video-Centered Deep Research Report Generation. Given a video and user request, an agent identifies research questions, retrieves external multimodal evidence, and produces an interactive report linked to relevant video moments. This task has direct practical value because it helps users locate relevant moments, verify claims, reproduce demonstrated procedures, and make informed decisions from video content. We present a skill-based workflow and OmniDR-Bench for this task. For evaluation, we propose Omni Atomic Rubric Trees (Omni-ARTs). Each tree contains three dimensions, 23 shared directions, and task-specific atomic binary criteria. The directions test audiovisual grounding, multimodal evidence use, and interactive presentation. "},{"hfUrl":"https://huggingface.co/papers/2610.30755","url":"https://arxiv.org/abs/2610.30755","pdf":"https://arxiv.org/pdf/2610.30755.pdf","id":"arxiv:2610.30755","announceDate":"2026-10-23","tags":["Agentic RAG","Agentic Search","Evaluation"],"source":"hf","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30755","topics":["Agentic RAG","Agentic Search","Evaluation"],"authors":["Zhengye Bao","Shengtao Zhang","Haokai Zhang","Shiqi Lou","Muning Wen","Minnan Luo"],"title":"Is Complex Agentic Memory Always Needed? Naive RAG Is Stronger Than We Thought","date":"2026-10-23","upvotes":15,"abstract":"LLM memory is widely used in long-term conversation understanding. Agentic memory systems often use mutation, structural organization, learned retrieval strategies, or other complex operations. Is this complexity always necessary? We study Raw-RAG, a naive RAG baseline using dense retrieval and reranking over raw history to supply evidence to a reader LLM. Across LoCoMo, LongMemEval, MEME, and MemoryAgentBench, Raw-RAG ranks first among the compared memory systems in six of seven benchmark-model settings, outperforming the strongest compared agentic memory system by 0.13-5.53 points. We investigate why raw-history retrieval remains competitive. Evidence analysis shows that its higher coverage of necessary evidence can offset lower utilization. Useful evidence includes both answer values and the relations and dependency paths needed to derive them. Even complete access to transformed memo"},{"hfUrl":"https://huggingface.co/papers/2610.31305","url":"https://arxiv.org/abs/2610.31305","pdf":"https://arxiv.org/pdf/2610.31305.pdf","id":"arxiv:2610.31305","announceDate":"2026-10-23","tags":["LLM Training"],"source":"hf","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31305","topics":["LLM Training"],"authors":["Hongcan Guo","Yian Zhao","Feng Wang","Shen Nie","Guoqiang Wei","Yan Zeng","Hengshuang Zhao"],"title":"Cola2: Co-Adaptive Hierarchical Language Modeling with Continuous Semantic Compression and Balanced Discrete Generation","date":"2026-10-23","upvotes":15,"abstract":"Hierarchical language generation separates continuous semantic modeling from discrete text realization, but its effectiveness depends on what the latent space compresses and how the discrete generator uses it. We propose Cola2, a framework that jointly studies continuous semantic compression, the balance between reconstruction and generation, and continuous-discrete co-adaptation. Cola2 dynamically segments text into semantic spans, controls the compression rate through auxiliary-loss-free negative feedback, and combines reconstruction and generation supervision to learn compact, predictive latent representations. A block-causal masked diffusion decoder is trained with clean, noisy, and dropped latent conditions, while classifier-free guidance adjusts the balance between semantic reconstruction and autonomous generation. Token-prediction gradients update the encoder through the latents, "},{"hfUrl":"https://huggingface.co/papers/2610.30866","url":"https://arxiv.org/abs/2610.30866","pdf":"https://arxiv.org/pdf/2610.30866.pdf","id":"arxiv:2610.30866","announceDate":"2026-10-23","tags":["Planning","Evaluation"],"source":"hf","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30866","topics":["Planning","Evaluation"],"authors":["Zhuoran Zhang","Yang Shi","Qixun Wang","Tengfei Liu","Yuqi Tang","Xuanyu Zhu","Yizhuo Jia","Jingyun Hua","Shixuan Liu","Xianghua Ying","Haotian Wang","Yuanxing Zhang","Pengfei Wan","Wenjing Yang"],"title":"Verus-Insight: Towards Explainable Artifact Detection in AI-Generated Videos","date":"2026-10-23","upvotes":12,"abstract":"Recent advances in video generation have made synthetic videos increasingly realistic, placing greater demands on reliable AI-generated video detection. Existing artifact-based detectors typically identify generation artifacts as evidence for source prediction, yet they may either fail to recognize subtle artifacts or reach the correct source decision without faithfully identifying the evidence underlying it. In this work, we systematically investigate how to design and train effective artifact detectors and formulate artifact detection as a structured process comprising three complementary capabilities: Inspection Planning, which determines what should be examined; Evidence Verification, which verifies whether the inspected content exhibits genuine generation artifacts; and Evidence Aggregation, which integrates the verified evidence into the final source decision. Building on this form"},{"hfUrl":"https://huggingface.co/papers/2610.31494","url":"https://arxiv.org/abs/2610.31494","pdf":"https://arxiv.org/pdf/2610.31494.pdf","id":"arxiv:2610.31494","announceDate":"2026-10-23","tags":["VLM Training","Reasoning","Planning","Computer Use","Evaluation"],"source":"hf","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31494","topics":["VLM Training","Reasoning","Planning","Computer Use","Evaluation"],"authors":["Advait Gupta","Sachin Konan","Tom Yin","Gabriel Sarch","Zhuang Liu"],"title":"AgentVQA: A Unified Benchmark for Agentic Visual Understanding","date":"2026-10-23","upvotes":11,"abstract":"Vision-language models (VLMs) can perform a broad range of tasks across diverse settings, yet their performance in agentic contexts remains poorly understood. Although online evaluations in simulators and real-world environments are essential for measuring interactive agent performance, they are costly and challenging to scale. Complementary offline VQA benchmarks can enable faster and more reliable comparisons across agentic domains, yet existing benchmarks remain limited and fragmented. To address this gap, we introduce AgentVQA, an offline benchmark for evaluating VLMs on realistic agentic scenarios across five agent domains: Web Agents, Robotics, Egocentric Videos, Games, and Spatial Planning. We build AgentVQA by manually selecting 1000 challenging, real-world agent examples from 23 source datasets and adapting them for reliable offline evaluation. The resulting benchmark preserves "},{"hfUrl":"https://huggingface.co/papers/2610.31466","url":"https://arxiv.org/abs/2610.31466","pdf":"https://arxiv.org/pdf/2610.31466.pdf","id":"arxiv:2610.31466","announceDate":"2026-10-23","tags":["Code Agent","Hallucination","Evaluation","Fine-tuning"],"source":"hf","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31466","topics":["Code Agent","Hallucination","Evaluation","Fine-tuning"],"authors":["Ruicong Liu","Liangyang Ouyang","Fengbo Lan","Zhixiang Wang","Kaipeng Zhang"],"title":"AnyGameRenderer: Entity-Consistent Generative Rendering Across Games and an Entity-Level Benchmark","date":"2026-10-23","upvotes":10,"abstract":"AI coding agents can now build small playable games in minutes, but the results usually look like programmer art: gray blockouts, colored geometric primitives, and flat semantic blobs. We present AnyGameRenderer, a video-to-video generative renderer that turns such footage into high-quality visuals with characters, motion detail, and effects. Throughout, it keeps the layout, camera, and every entity's position and timing intact. Our AnyGameRenderer generalizes across a wide range of genres that agents build, such as tower defense, auto-battlers, top-down survivors, turn-based battles, kart racing, and crowd runners. AnyGameRenderer takes plain video as its game-state input, with no complex representations such as engine G-buffers, per-object class labels, or low-poly proxies. Gray blockouts, colored primitives, semantic maps, and wireframes all work as input. It also preserves entity cor"},{"hfUrl":"https://huggingface.co/papers/2610.31668","url":"https://arxiv.org/abs/2610.31668","pdf":"https://arxiv.org/pdf/2610.31668.pdf","id":"arxiv:2610.31668","announceDate":"2026-10-23","tags":["Evaluation","World Model"],"source":"hf","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31668","topics":["Evaluation","World Model"],"authors":["Shengqiong Wu","Meng Luo","Bobo Li","Ziwei Liu","Shuicheng Yan","Ming-Hsuan Yang","Philip Torr","Hao Fei"],"title":"Reading, Writing, Sharing, and Interacting with the World through Video","date":"2026-10-23","upvotes":8,"abstract":"Video foundation models have advanced rapidly in understanding and generating visual sequences, while video world models seek to capture the underlying dynamics of the world they depict. Despite their different objectives, both concern the relationship between video observations and an evolving world. This survey adopts world modeling as a unifying lens for examining these developments. Viewing an observed video as a partial, lossy, and temporally ordered projection of a latent temporal world, we organize the literature around four complementary operations: reading infers world properties from observed video; writing synthesizes video from specified or learned world conditions; sharing integrates understanding and generation through common modeling mechanisms; and interacting predicts and updates world states under actions and evolving observations. This perspective distinguishes tempora"},{"hfUrl":"https://huggingface.co/papers/2610.30882","url":"https://arxiv.org/abs/2610.30882","pdf":"https://arxiv.org/pdf/2610.30882.pdf","id":"arxiv:2610.30882","announceDate":"2026-10-23","tags":["Post-Training","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"source":"hf","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30882","topics":["Post-Training","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"authors":["Zhizhuo Kou","Sizai Hou","Long Chen","Jian Yang","Junyu Luo","Jingshu Peng","Wenkai Zhang","Sirui Han","Yike Guo"],"title":"Inherited, Not Invented: Tracing the Provenance of Wait in Reasoning Models","date":"2026-10-23","upvotes":7,"abstract":"Reinforcement learning (RL) is credited with teaching reasoning models to write {wait} before reconsidering a step, yet large RL accuracy gains do not require the word. This view can confuse what RL discovers with what a model inherits from its training data. We trace the word through open models' training histories, reading it with label-free indices of frequency, position, form and usage and an injected-error test, all computed from sampled outputs. We find that zero-RL almost never coins the marker: on bases that lack the word, RL raises MATH-500 accuracy substantially while {wait} stays near absent. It arrives with training data: mid-training in OLMo-3, and fine-tuning on reasoning traces installs it in most models whose base lacks it. Where the base already uses it, both released RL-Zero recipes (OLMo-3, MiMo) multiply it, whereas KL-free GRPO from the same base does not; OLMo-3's r"},{"hfUrl":"https://huggingface.co/papers/2610.31062","url":"https://arxiv.org/abs/2610.31062","pdf":"https://arxiv.org/pdf/2610.31062.pdf","id":"arxiv:2610.31062","announceDate":"2026-10-23","tags":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"source":"hf","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31062","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"authors":["Arnon Mazza","Elad Levi"],"title":"SCOPE: Compiling Natural-Language Policies into Neurosymbolic Predicate Programs","date":"2026-10-23","upvotes":7,"abstract":"Policy enforcement for LLM agents has shifted from single-turn content moderation to compound, application-specific policies evaluated over multi-turn transcripts and tool-call trajectories. Fine-tuned guardrail models are efficient but degrade on compound policies, and while LLM-as-a-judge approaches achieve higher accuracy, they incur high inference cost and tend to produce unstable predictions. Neurosymbolic methods offer a natural alternative, decomposing the policy into narrow neural decisions composed under explicit logic. However, existing symbolic layers lack the required expressiveness and are optimized against fixed data rather than the policy itself. To address this, we introduce SCOPE, which compiles a policy into an executable program of neural predicates executed by small models, deterministic extractors, and code that composes their outputs. The program is optimized jointl"},{"hfUrl":"https://huggingface.co/papers/2610.30340","url":"https://arxiv.org/abs/2610.30340","pdf":"https://arxiv.org/pdf/2610.30340.pdf","id":"arxiv:2610.30340","announceDate":"2026-10-23","tags":["Evaluation","Fine-tuning"],"source":"hf","submittedDate":"2026-10-21","arxiv":"https://arxiv.org/abs/2610.30340","topics":["Evaluation","Fine-tuning"],"authors":["NVIDIA",":","Sérgio Agostinho","Maximilian Apodaca","Emmanuel Attia","Guillem Braso","George Dong","Ilya Fedorov","Michele Fenzi","Gang Huang","Jiahui Huang","Shengyu Huang","Bingxin Ke","Laura Leal-Taixé","Kuan-Ting Lee","Mingxuan Liu","Tian Liu","Tim Meinhardt","Aljoša Ošep","Naveen Kumar Rai","Kefei Ren","Cristiano Saltori","Keqiang Wu","Ning Xu","Fei Xue","Jin-Bey Yu","Lei Zhang","Qunjie Zhou"],"title":"Foundation4D: Towards a unified perception and reconstruction model for autonomous vehicles","date":"2026-10-23","upvotes":4,"abstract":"We introduce Foundation4D, a unified feed-forward model for geometry estimation, 3D detection, semantic occupancy, and Gaussian reconstruction from multi-camera driving video. A shared backbone uses factorized spatiotemporal attention to efficiently combine observations across cameras and time. Our video inference pipeline uses pose graph optimization to refine camera trajectories and assembles object tracks across input windows. We also develop a data annotation pipeline and release PAI-Foundation4D, a benchmark with dense depth and semantic occupancy labels for 1,253 driving clips. With benchmark-specific fine-tuning, Foundation4D achieves the lowest depth AbsRel on Waymo and nuScenes, the highest detection mAP on nuScenes, and the highest occupancy mIoU on OpenOccupancy among the compared methods. Our task-combination study shows benefits for both detection and geometry: co-training d"},{"hfUrl":"https://huggingface.co/papers/2610.31329","url":"https://arxiv.org/abs/2610.31329","pdf":"https://arxiv.org/pdf/2610.31329.pdf","id":"arxiv:2610.31329","announceDate":"2026-10-23","tags":["LLM Training","VLM Training","Evaluation"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31329","topics":["LLM Training","VLM Training","Evaluation"],"authors":["Tianming Liang","Junyi Pan","Yuxi Li","Canmiao Fu","Zhipeng Huang","Chong Sun","Chen Li","Jing Lyu"],"title":"WeVisOne-VL: Unified Visual Perception from Objects to Pixels","date":"2026-10-23","upvotes":232,"abstract":"Existing vision-language models (VLMs) remain unreliable for fine-grained visual perception. In this report, we present WeVisOne-VL (WeChat Vision All-in-One), a powerful VLM that unifies object-level and pixel-level perception through structured next-token prediction. It supports multiple visual tasks including object detection, referring localization, counting, OCR, segmentation, and matting, enabling localization at any user-specific granularity, from points and boxes to masks and alpha mattes. Architecturally, we integrate a lightweight pixel decoder into the VLM via a special <OBJ> token to generate instance-level pixel outputs. We train the model with a three-stage curriculum SFT followed by mixed-task RL. Across over 30 benchmarks, WeVisOne-VL demonstrates leading performance on both object-level and pixel-level tasks, while maintaining robust rejection for object-absent queries. "},{"hfUrl":"https://huggingface.co/papers/2610.30949","url":"https://arxiv.org/abs/2610.30949","pdf":"https://arxiv.org/pdf/2610.30949.pdf","id":"arxiv:2610.30949","announceDate":"2026-10-23","tags":["Post-Training","LLM Training"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30949","topics":["Post-Training","LLM Training"],"authors":["A. Jian Yang","An Huang","Bo Dan","Chen Mu","Chengran Yang","Chuan Shi","Feng Chang","Hongxin Li","Hongyuan Tao","Jinxing Zhang","Jujie He","Kun Wang","Lin Jing","Ming Yang","Qicheng Hu","Renyuan Li","Shark Liu","Shawn Guo","Shi Qing","Shi Zhong","Tianyu Zheng","Wei Liu","Wei Zhang","Wenrui Cai","Wenxiao Chen","Xuxing Chen","Yan Xing","Yi Xing","Yifan Luo","Yiran Xing","Yizhi Li","Yongsheng Kang","Yucheng Ding","Yue Song","Yun Qing","Yunqi Liu","Zelong Huang","Zhengmao Ye","Zhentao Fan","Zhiteng Li","Ziling Huang","Bihong Tang","Bingli Wang","Ce Jun","Changhao Chen","Chen Hu","Chen Xiao","Chi Liu","Chunjiang Ge","Danyang Li","Deyang Kong","Dian Qi","Ding Tan","Evan Yang","Fanglin Xu","Fei Bai","Gang Liu","Guochang Li","Hao Tang","Haoran Feng","Haowen Wang","Huahao Hu","Huanjin Yao","Huatong Song","Jia Deng","Jiajun Wu","Jialiang Cheng","Jiayi Liang","Jiayi Wu","Jie Deng","Jiejun Tan","Jing Yang","Jingda Xu","Junhang Cheng","Junxiao Liu","Kai Lv","Kaixiang Pan","Kecheng Lu","Kun Zeng","Kun Zheng","Kunbo Ding","Liang Qiu","Lingyi Sun","Luan Zhang","Mengxiao Lv","Ning Dong","Pei Wang","Peng Zhang","Qingsong Cai","Qixiang Yin","Qiyao Wang","Renbiao Liu","Renfei Dang","Ruihang Li","Ruirui Huang","Shanhui Yin","Shen Jian","Shengjie Fang","Shikai Li","Shinan Zhang","Shiqi Chen","Shuai Liu","Shuangqi Li","Shuo Tang","Shuqing Deng","Sijin Hao","Siwei Wu","Siyue Wang","Tao Hai","Tao Ren","TingYang Chen","Wei Shao","Weicheng Gu","Weihan Peng","Wenlong Miao","Xavier Yu","Xiangyuan Ji","Xiaocheng Li","Xiaodong Huang","Xiaohan Ge","Xiaoxiang Shi","Xiaoyang Zhang","Xiaoyu Yang","Xidong Wang","Xin Li","Xinyu Tang","Xiyuan Yang","Xudong Ma","Ya Tong","Yachao Wang","Yang Tian","Yaxin Du","Yeli Ruan","Yi Wang","Yi Yu","Yibin Feng","Yibo Tan","Yihang Wang","Yiming Ju","Yinda Chen","Yinda Chen","Yingjie Du","Yiwei Liu","Yizhi Zhou","Yuan Wei","Yuli Chen","Yuqi Zhu","Yuwen Li","Yuxi Dong","Yuxuan Zhang","Yuyang Song","Zhange Zhang","Zhaohan Zhang","Zhaoyi Li","Zhen Zhang","Zhengbo Zhang","Zhihang Hu","Zhiwei Yu","Zhixin Xie","Zhiyu Chen","Zhizhao Luo","Zhongyuan Wu","Zhou Fang","Zhu Lin","Zhuocheng Gong","Zixi Zhao","Ziyang Zeng","Ziyi Wang","Ziyu Zhao","Ran Tao","Mingjie Tang","Chuan Hao","Peihao Wu","Jianzhou Wang","Nan Jiang","Yuan Zhi","Bryan Dai"],"title":"IQuest-Q1: Advancing Foundation Capabilities for Agentic CLI Systems","date":"2026-10-23","upvotes":86,"abstract":"We present IQuest-Q1, a sparse Mixture-of-Experts (MoE) agentic foundation model with 320B total parameters (15B activated). IQuest-Q1 is developed through a three-stage process: (1) stable and efficient pre-training, combining Stable SplitNorm, Muon, and muP with a two-stage curriculum whose second stage increases the coding-data mixture, preserving a wide stability margin between safe and optimal learning rates; (2) fine-grained mid-training, expanding the data mixture across domains and formats and progressively extending the context; and (3) multi-scaffold with multi-version post-training, combining SFT, domain-specialized RL, and MOPD across various scaffolds to integrate complementary training signals and strengthen agentic coding capabilities. Furthermore, model merging combines different experts and checkpoints from different stages while mitigating conflicts among their paramete"},{"hfUrl":"https://huggingface.co/papers/2610.30753","url":"https://arxiv.org/abs/2610.30753","pdf":"https://arxiv.org/pdf/2610.30753.pdf","id":"arxiv:2610.30753","announceDate":"2026-10-23","tags":["Reasoning","Evaluation"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30753","topics":["Reasoning","Evaluation"],"authors":["Yiming Zhang","Jiarui Guo","Haojia Wei","Yifei Liu","Yifan Yang","Hongjie Zhang","Xue Yang","Zhihang Zhong"],"title":"FilmFlow: Agentic System for 3D Virtual Film Cinematography","date":"2026-10-23","upvotes":26,"abstract":"Complex camera motion is central to visual storytelling, yet translating cinematographic intent into controllable, executable camera trajectories remains challenging. We introduce FilmFlow, an agentic framework that converts natural-language instructions or reference videos into explicit camera trajectories for dynamic 3D environments. To generate these trajectories, a Director agent constructs executable camera plans by composing high-level motions from concurrent atomic operations that jointly control translation, rotation, and framing. The Director is supported by three specialized agents: an Interpreter that extracts scene-grounded cinematographic intent, a Scout that selects initial viewpoints, and a Critic that evaluates rendered results and provides visual feedback for iterative plan refinement. We also introduce CinemaBench, comprising 150 Blender scenes from self-created and lic"},{"hfUrl":"https://huggingface.co/papers/2610.31198","url":"https://arxiv.org/abs/2610.31198","pdf":"https://arxiv.org/pdf/2610.31198.pdf","id":"arxiv:2610.31198","announceDate":"2026-10-23","tags":["Evaluation"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31198","topics":["Evaluation"],"authors":["Ofek Avivi","Eliron Rahimi","Avi Mendelson","Chaim Baskin"],"title":"Different Tasks, Different Timesteps: Temporal Task-Aware Quantization for Diffusion Language Models","date":"2026-10-23","upvotes":11,"abstract":"Diffusion Language Models (DLMs) introduce unique quantization challenges due to their iterative denoising process. In this work, we reveal that quantization sensitivity is both taskand time-dependent, with different downstream tasks exhibiting distinct precision requirements across denoising steps. We further show that these patterns can be predicted without groundtruth labels or task-specific evaluation metrics. Building on these findings, we introduce T 2Quant, a task and time-aware mixedprecision quantization framework that uses a label-free sensitivity signal to optimally allocate activation precision across denoising steps under a fixed bit-width budget. Extensive experiments across three DLMs and six benchmarks demonstrate that T 2Quant consistently improves the average accuracy of existing quantization methods, achieving gains of up to 6.7 percentage points under the same budget."},{"hfUrl":"https://huggingface.co/papers/2610.31372","url":"https://arxiv.org/abs/2610.31372","pdf":"https://arxiv.org/pdf/2610.31372.pdf","id":"arxiv:2610.31372","announceDate":"2026-10-23","tags":["Agentic Search","Evaluation"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31372","topics":["Agentic Search","Evaluation"],"authors":["Jiening Siow","Amy Xin","Junjie Wang","Ziyu Tang","Zijun Yao","Yunjia Qi","Fanjin Zhang","Lei Hou","Jie Tang","Juanzi Li"],"title":"RIDAR: Safeguarding Research Integrity in Autonomous Research Agents via Automated Detection and Runtime Intervention","date":"2026-10-23","upvotes":8,"abstract":"Autonomous research agents are increasingly used to automate large portions of scientific research, yet they are prone to research integrity violations (RIVs): behaviors that compromise the validity, reproducibility, or faithfulness of the research process. We present RIDAR, a framework for automated RIV detection and runtime intervention. First, we introduce RIVT, a comprehensive taxonomy of 14 RIV types spanning the full research lifecycle. Building on RIVT, we present RIDAR-post-hoc, a framework to detect RIVs within agent trajectories. RIDAR-post-hoc achieves 85.2% F1 performance on RIV-Gold, a benchmark for RIV detection with 60 expert-annotated trajectories. Applying RIDAR-post-hoc to RIV-Wild, a dataset of 300 agent trajectories across 50 distinct research tasks, we detect 3,964 RIV instances in 99.7% of trajectories, revealing the prevalence of RIVs in current agents. Finally, we"},{"hfUrl":"https://huggingface.co/papers/2610.31651","url":"https://arxiv.org/abs/2610.31651","pdf":"https://arxiv.org/pdf/2610.31651.pdf","id":"arxiv:2610.31651","announceDate":"2026-10-23","tags":["Code Agent"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31651","topics":["Code Agent"],"authors":["Ava Pun","Kevin Dai","Sally Chen","Maxwell Jones","Ruixuan Liu","Kangle Deng","Changliu Liu","Maneesh Agrawala","Deva Ramanan","Jun-Yan Zhu"],"title":"BrickWright: Agentic Creation of Physically Feasible Brick Builds","date":"2026-10-23","upvotes":7,"abstract":"Frontier coding agents are becoming increasingly adept at 3D modeling. Yet, they still face challenges when building objects meant to be assembled in the physical world, often creating invalid assemblies with floating, colliding, or disconnected parts. We argue that providing agents with tools for assembling builds and verifying their physical feasibility is sufficient for them to produce physically valid assemblies that still adhere to input prompts. Focusing on the domain of LEGO brick builds, we present BrickWright, a framework for generating physically feasible brick builds from text or image prompts using pre-trained agents, where a build is physically feasible if it uses only real parts, has no colliding or floating parts, and forms a connected structure if possible. BrickWright guides agents to create builds by writing code with BrickLayer, a Python toolkit with two main component"},{"url":"https://arxiv.org/abs/2610.30834","pdf":"https://arxiv.org/pdf/2610.30834.pdf","id":"arxiv:2610.30834","announceDate":"2026-10-23","tags":["Post-Training","LLM Training","VLM Training","Reasoning","Evaluation"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30834","topics":["Post-Training","LLM Training","VLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"authors":["Zhaolu Kang","Tailong Luo","Chenxin Li","Yingjie He","Zhenyu Yu","Fengyu Zhou","Jiachen Qian","Lei Wei","Shuang Chen","Jiachen Li","Eric Hanchen Jiang","Rongchao Zhang","Zhengtao Yao","Hoi Leong Lee","Guansu Wang","Kaiyue Zhou"],"title":"RECAP: Looking Once Is Not Enough for Vision-Language Reasoning","date":"2026-10-23","upvotes":0,"abstract":"Long chain-of-thought reasoning improves vision-language models (VLMs), but it also exposes a temporal grounding failure: as generation unfolds, models may drift from image evidence while reinforcement learning still provides only a final-answer reward. We study this gap through visual revisit, a temporally localized reactivation of image evidence during reasoning. Across three VLM backbones, revisit peaks are predictive of correctness and causally linked to performance: masking them degrades accuracy more than masking non-peaks, while injecting revisit-like peaks into failed rollouts partially restores correct answers. Control analyses show that this signal is not explained by raw attention strength, uncertainty, logit margin, or hidden-state norm. We propose RECAP, a GRPO-compatible training method that turns detached revisit traces into a credit-assignment signal. RECAP uses revisit-c"},{"url":"https://arxiv.org/abs/2610.30705","pdf":"https://arxiv.org/pdf/2610.30705.pdf","id":"arxiv:2610.30705","announceDate":"2026-10-23","tags":["Agentic RAG","Agentic Search","Post-Training","Reasoning","Evaluation"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30705","topics":["Agentic RAG","Agentic Search","Post-Training","Reasoning","Evaluation","Fine-tuning"],"authors":["Yang Liu","Zhiqiang Yuan","Shu-Dong Huang","Jiancheng Lv","Liwei Yang","Qiwei Yan","Kailin Lv","Jinchao Zhang"],"title":"ULME: Predictive Coupling for Mutually Reinforcing Embedding and Language Modeling","date":"2026-10-23","upvotes":0,"abstract":"Text embedding and text generation are two of the most useful capabilities of modern large language models, yet they are typically provided by separate specialized models (an embedder and a generator) trained with incompatible objectives and deployed side by side in retrieval-augmented generation and agent systems. Recent unified embedding-generation models such as GritLM share parameters between the two capabilities, but they either switch attention regimes between modes or optimize embedding and language modeling as parallel objectives that never supervise each other. We argue that these designs are only partially unified: the two capabilities coexist on the same weights, but do not shape each other. We propose ULME, a post-training framework that unifies embedding and language modeling on a causal decoder-only LLM through predictive coupling. ULME inserts a chain of learnable slots be"},{"url":"https://arxiv.org/abs/2610.30435","pdf":"https://arxiv.org/pdf/2610.30435.pdf","id":"arxiv:2610.30435","announceDate":"2026-10-23","tags":["Agentic Search","Multi-Agent","Reasoning","Hallucination","Evaluation"],"source":"arxiv","submittedDate":"2026-10-21","arxiv":"https://arxiv.org/abs/2610.30435","topics":["Agentic Search","Multi-Agent","Reasoning","Hallucination","Evaluation","RL for LLM"],"authors":["Taewhoo Lee","Minju Song","Jungwoo Park","Chanwoong Yoon","Junha Jung","Hyeon Hwang","Sanghoon Lee","Minbyul Jeong","Jaewoo Kang"],"title":"Self-Assessment Reinforcement Learning for Search-State Awareness in Retrieval-Augmented Large Language Models","date":"2026-10-23","upvotes":0,"abstract":"Recent advances in search agents have enabled large language models to tackle complex tasks by retrieving and synthesizing external information. However, existing search agents often lack search-state awareness, i.e., the ability to recognize what information has been obtained and what remains missing, leading to hallucinated reasoning and prematurely terminated search. To address this limitation, we propose Self-Assessment Reinforcement Learning (SARL), a reinforcement learning framework in which models learn to recognize their own search state during training and improve their search behavior accordingly, without requiring additional assessment at test time. SARL achieves this through a dual reward design that captures the corrective effect of each assessment while penalizing excessive reliance on it, jointly encouraging effective and efficient search trajectories. Under this setup, SA"},{"url":"https://arxiv.org/abs/2610.30202","pdf":"https://arxiv.org/pdf/2610.30202.pdf","id":"arxiv:2610.30202","announceDate":"2026-10-23","tags":["Agent Safety","Reasoning","Evaluation","Alignment","Fine-tuning"],"source":"arxiv","submittedDate":"2026-10-21","arxiv":"https://arxiv.org/abs/2610.30202","topics":["Agent Safety","Reasoning","Evaluation","Alignment","Fine-tuning"],"authors":["Yiheng Li","Jingyue Li"],"title":"MPIDetector: Detecting Multi-modal Prompt Injection via LLM-based Reasoning","date":"2026-10-23","upvotes":0,"abstract":"With the rapid integration of Multi-modal Large Language Models (MLLMs) into real-world applications, Prompt Injection (PI) has emerged as a critical security threat. Attackers can conceal malicious instructions within textual narratives or visual inputs to bypass safety alignment. Existing approaches, such as signature- and perplexity-based methods, rely heavily on pattern matching, making them insufficient to detect sophisticated, cross-modal PI payloads. In this paper, we propose a novel detection framework, called MPIDetector, that leverages LLMs' intrinsic reasoning capabilities via few-shot In-Context Learning (ICL). Instead of fine-tuning, we provide the model with specific prompt templates and representative attack examples, enabling it to scrutinize the semantic intent of input across modalities. We constructed a comprehensive evaluation benchmark comprising eight textual and se"},{"url":"https://arxiv.org/abs/2610.31256","pdf":"https://arxiv.org/pdf/2610.31256.pdf","id":"arxiv:2610.31256","announceDate":"2026-10-23","tags":["Agentic RAG","Agentic Search","Hallucination","Evaluation","Fine-tuning"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31256","topics":["Agentic RAG","Agentic Search","Hallucination","Evaluation","Fine-tuning"],"authors":["Tirana Noor Fatyanosa","Ummu Ditya Erliana","Mahendra Data","Muhammad Nurwegiono","Eleazar Tadeo Eman","Alham Fikri Aji"],"title":"IndoNutriQA: An Indonesian Clinical Nutrition Question Answering Benchmark","date":"2026-10-23","upvotes":0,"abstract":"Clinical Question Answering (QA) underpins Clinical Intelligent Decision Support Systems, but progress is severely limited for low-resource languages such as Indonesian by the absence of public domain-specific data. We introduce IndoNutriQA, an expert-curated Indonesian clinical QA benchmark of 911 question-answer pairs built from real clinical-nutrition reports. Rather than a large-scale training corpus, it is positioned as a high-quality evaluation resource: every pair is grounded in a clinically relevant context, enriched with structured metadata (anthropometric assessment, medical diagnosis, document provenance, chunk segmentation). Eight standardised question types following the Nutrition Care Process (NCP), including the Problem, Etiology, Sign and Symptom (PES) diagnosis statement, are answered for every report, which was written by a graduate-level dietetic intern, by one of thre"},{"url":"https://arxiv.org/abs/2610.30860","pdf":"https://arxiv.org/pdf/2610.30860.pdf","id":"arxiv:2610.30860","announceDate":"2026-10-23","tags":["Post-Training","LLM Training","Evaluation","Fine-tuning","Data Engine"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30860","topics":["Post-Training","LLM Training","Evaluation","Fine-tuning","Data Engine"],"authors":["Firoj Paudel"],"title":"Synthetic-to-Real Code-Switched ASR: A Spontaneous Nepali-English Podcast Benchmark","date":"2026-10-23","upvotes":0,"abstract":"Nepali-English code-switched conversational speech presents severe challenges for automatic speech recognition (ASR), chiefly through script confusion (inappropriate mixing of Devanagari and Latin orthography) and elevated error rates at language switch points. Supervised fine-tuning (SFT) can adapt multilingual foundation models, but human code-switched audio is expensive to collect and annotate. We curate a new benchmark of 13,044 spontaneous podcast utterances (15.45 h total; 10,214 test, 2,830 dev), audited and verified to eliminate machine translation leakages and acoustic loops. We investigate a two-stage synthetic-to-real adaptation framework: Stage 1 applies SFT on 0.95 h of speech synthesized via a multi-speaker, dual-engine TTS pipeline; Stage 2 explores Group Relative Policy Optimization (GRPO) with transcription and script rewards. We find that synthetic SFT provides the prim"},{"url":"https://arxiv.org/abs/2610.30963","pdf":"https://arxiv.org/pdf/2610.30963.pdf","id":"arxiv:2610.30963","announceDate":"2026-10-23","tags":["Reasoning","Planning","Evaluation","Fine-tuning","Multimodal Agent"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30963","topics":["Reasoning","Planning","Evaluation","Fine-tuning","Multimodal Agent"],"authors":["Jaishnoor Kaur","Josef Horáček","Ian Waskom","Sayak Saha Roy"],"title":"ReDence: A Hybrid Agentic and Decision-Model Framework for Rapid, Evidence-Grounded Detection of Modern Social Engineering Scams","date":"2026-10-23","upvotes":0,"abstract":"Detecting online social engineering (SE) scams often requires examining website workflows, verifying claims against external sources, and connecting evidence across multiple pages. Existing detectors provide limited support for these investigations, leaving analysts to manually gather and validate evidence, which inevitably delays detection and subsequent takedown of these attacks. To address this gap, we present ReDence, an open-source hybrid framework for adaptive, evidence-grounded detection across diverse SE scam categories. ReDence combines two locally hosted models with complementary responsibilities: a fine-tuned multimodal agentic Investigator (Qwen3.5-4B) that performs investigative planning, evidence interpretation, and reporting, and a specialized Decider (Tev1) that handles binary and multiple-choice tasks, including browser-action selection, evidence assessment, and decision"},{"url":"https://arxiv.org/abs/2610.30663","pdf":"https://arxiv.org/pdf/2610.30663.pdf","id":"arxiv:2610.30663","announceDate":"2026-10-23","tags":["Post-Training","LLM Training","Evaluation","RL for LLM"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30663","topics":["Post-Training","LLM Training","Evaluation","RL for LLM"],"authors":["Tim Wenjie Hu","Evelyn Nafula Ouma","Benjamin Akera","John A. Quinn"],"title":"Group Relative Policy Optimisation Improves Multilingual Speech Recognition in Low-Resource Languages","date":"2026-10-23","upvotes":0,"abstract":"Autoregressive encoder-decoder speech recognition models trained with teacher forcing can suffer from exposure bias, limiting their ability to recover from their own prediction errors at inference time. Recent work has shown that reinforcement learning with Group Relative Policy Optimisation (GRPO) improves speech recognition in major languages with LLM-based models. We extend this line of work to smaller, non-LLM encoder-decoder ASR models, using Whisper-large-v3 as a case study across 51 African languages. The benefits of this approach are most pronounced when training data is scarce or when input audio is noisy or degraded. Our resulting model, SunflowerASR, achieves the best published macro-averaged WER on the AfriVox-v2 (0.227) and SimbaBench (0.372) benchmarks, and is publicly available."},{"url":"https://arxiv.org/abs/2610.30657","pdf":"https://arxiv.org/pdf/2610.30657.pdf","id":"arxiv:2610.30657","announceDate":"2026-10-23","tags":["Post-Training","LLM Training","Fine-tuning","World Model"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30657","topics":["Post-Training","LLM Training","Fine-tuning","World Model"],"authors":["Viet-Thanh Pham","Thuy-Trang Vu","Zhuang Li","Lizhen Qu","Gholamreza Haffari"],"title":"Anticipating Social Consequences with Distributional World Models","date":"2026-10-23","upvotes":0,"abstract":"Social world models predict how interactions develop after an action, helping agents negotiate, cooperate and mediate. In these situations, one action can lead to several plausible futures, hence predicting only one future can overlook consequential alternatives, while exploring them through repeated simulations increases inference cost. We propose DSWM, a Distributional Social World Model that predicts alternative responses, their probabilities and immediate and final outcome values in one output per candidate action. We train a 4B model on repeated simulations using supervised fine-tuning and GRPO. At inference time, the actor uses these possible consequences to choose an action. Across three seen and two unseen environments, with interaction backbones absent from training collection, DSWM achieves the best average performance on 13 of 15 metrics. Ablations show that retaining multiple"},{"url":"https://arxiv.org/abs/2610.30644","pdf":"https://arxiv.org/pdf/2610.30644.pdf","id":"arxiv:2610.30644","announceDate":"2026-10-23","tags":["Reasoning","Alignment","Fine-tuning","Reflection"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30644","topics":["Reasoning","Alignment","Fine-tuning","Reflection"],"authors":["Zhiming Meng"],"title":"Speculative Acceptance Does Not Decay with Position: A Full-Length Diagnostic on Long Chain-of-Thought with Independent Drafts","date":"2026-10-23","upvotes":0,"abstract":"The claim that speculative-decoding acceptance rate decays as a chain-of-thought grows longer has become a de facto industry narrative, motivating draft-model co-design and position-aware training. Nearly all direct evidence comes from trained drafters whose offline training length is far shorter than inference, so a purely positional law has never been isolated. We present the first systematic, full-length measurement of acceptance rate as a function of generation position on MATH-500 (all 500 problems), under greedy and sampling decoding, with two independent drafts against DeepSeek-R1-Distill-Qwen-7B: a same-family draft (DeepSeek-R1-Distill-Qwen-1.5B) and a cross-family draft (Qwen2.5-1.5B-Instruct), yielding about 1.78M verification rounds. Using within-problem paired tests, we find that after isolating a greedy-decoding repetition pathology, acceptance rate does not decay with posi"},{"url":"https://arxiv.org/abs/2610.31355","pdf":"https://arxiv.org/pdf/2610.31355.pdf","id":"arxiv:2610.31355","announceDate":"2026-10-23","tags":["Multi-Agent","Reasoning","Evaluation","Reflection"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31355","topics":["Multi-Agent","Reasoning","Evaluation","Reflection"],"authors":["Ping-Lin Kuo","Suman Navaratnarajah","Christian Frey","Gresa Shala","Josif Grabocka"],"title":"Muffin - A Shared Memory Buffer for Asynchronous AI Agents","date":"2026-10-23","upvotes":0,"abstract":"The rise of Agentic AI systems has changed the landscape of artificial intelligence by enabling strong reasoning capabilities through specialized multi-agent interaction with structured self-reflection. However, in target-driven reasoning tasks, single- and multi-agent systems are often on par in terms of performance gains. A major challenge is that failures often arise from an ineffective exchange of critical information during inter-agent interaction and coordination. Different from existing multi-agent debate paradigms that rely on synchronous turn-taking and sharing information across different agents, we propose an inter-agent protocol based on shared Memory bUFFer INference - referred to as MUFFIN - in an asynchronous agentic framework. In the first step, an orchestrator routes queries based on their reasoning demands and delegates demanding ones to a multi-agent setting, where a s"},{"url":"https://arxiv.org/abs/2610.30485","pdf":"https://arxiv.org/pdf/2610.30485.pdf","id":"arxiv:2610.30485","announceDate":"2026-10-23","tags":["Agentic RAG","Agentic Search","Memory","Evaluation"],"source":"arxiv","submittedDate":"2026-10-21","arxiv":"https://arxiv.org/abs/2610.30485","topics":["Agentic RAG","Agentic Search","Memory","Evaluation"],"authors":["Jialin Li","Zhenhao Chen","Hanjun Luo","Hanan Salam"],"title":"Why Bother Me Again? Benchmarking Personal Agent Memory for Interaction Preferences","date":"2026-10-23","upvotes":0,"abstract":"Personal intelligence systems are taking on increasingly complex everyday tasks, yet repeated questions, unnecessary confirmations, and unwanted outreach can turn capable assistance into interaction burden. Reducing this burden requires agents to remember how users want to be assisted. However, existing memory benchmarks focus on factual recall and personalized answers and rarely test how agents learn and act on interaction preferences. We introduce MemPABench, an interactive environment for on-policy evaluation of memory in personal agents. MemPABench poses long-horizon tasks requiring agents to decide when to clarify, confirm, or act autonomously. Four grounded simulated users hold 14 preferences across work and personal contexts. Their feedback spans 99 sessions over four months, with five event-driven changes per user testing memory updates. We evaluate preference selection, delivere"},{"url":"https://arxiv.org/abs/2610.30611","pdf":"https://arxiv.org/pdf/2610.30611.pdf","id":"arxiv:2610.30611","announceDate":"2026-10-23","tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.30611","topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"authors":["Amirhossein Aghaei","Liangyan Li","Shiyi Yang","Shaohua Wang","Yan Wang"],"title":"Better Reasoning, Not Just Bigger Models: A Structure-Grounded Framework for Efficient and Reliable Inference","date":"2026-10-23","upvotes":0,"abstract":"Scaling large language models has substantially improved linguistic fluency, yet reliable autonomous agents require more than fluent generation. In multi-turn inference, current agentic systems often produce semantically plausible but structurally ungrounded reasoning, especially under incomplete observations. We propose Structure-Grounded Uncertainty Reduction (SGUR), a training-free framework that complements token-level generation with active uncertainty reduction over structured hypothesis spaces. SGUR represents incomplete observations as a query graph and aligns them with candidate hypothesis graphs through a prior-weighted partial graph matching mechanism, where database-derived empirical priors assign greater importance to decision-relevant relations rather than treating all graph edges uniformly. The resulting inference state is iteratively refined by an active information-gain "},{"url":"https://arxiv.org/abs/2610.31511","pdf":"https://arxiv.org/pdf/2610.31511.pdf","id":"arxiv:2610.31511","announceDate":"2026-10-23","tags":["VLM Training","Planning","Code Agent","Evaluation"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31511","topics":["VLM Training","Planning","Code Agent","Evaluation"],"authors":["Ziyi Jiao","Heng Zhang","Drishti Regmi","Xiaokang Ye","Lianhui Qin","Peter Yichen Chen"],"title":"DuoCook: An Overcooked-Inspired Benchmark for Visual Planning and Coordination","date":"2026-10-23","upvotes":0,"abstract":"Coordinating two players in a cooking task requires a vision-language agent to track changing scene states, sequence recipe steps, and allocate shared resources under a time budget. We introduce an Overcooked-inspired benchmark for evaluating these capabilities in Unreal Engine environments constructed using coding agents. A single vision-language model controls both players from top-down visual observations, selecting high-level actions while the engine executes navigation. The benchmark contains 20 maps in five categories. These categories support evaluation of centralized coordination under equipment contention, changing terrain, and handoff dependencies. A prop legend and pot ingredient-count indicators provide explicit visual cues, while grid-based destinations support spatial grounding. The evaluation compares four VLMs on all 20 maps, measuring task score, order completion, delive"},{"url":"https://arxiv.org/abs/2610.30167","pdf":"https://arxiv.org/pdf/2610.30167.pdf","id":"arxiv:2610.30167","announceDate":"2026-10-23","tags":["Agentic RAG","Agentic Search","Evaluation","Reflection"],"source":"arxiv","submittedDate":"2026-10-16","arxiv":"https://arxiv.org/abs/2610.30167","topics":["Agentic RAG","Agentic Search","Evaluation","Reflection"],"authors":["Maria Ana Cardei","Aniket Singh","Amir Moghadam","Srividhya Baikadi","Rashmi Shetty"],"title":"IRAH: Hierarchical Agentic Tree Search for Retrieval Pipeline Optimization","date":"2026-10-23","upvotes":0,"abstract":"Optimizing Information Retrieval (IR) pipelines for Retrieval-Augmented Generation (RAG) requires jointly selecting structural components and numerical hyperparameters under limited evaluation budgets. We introduce the Information Retrieval Agentic Harness (IRAH), which combines Language Agent Tree Search for IR (LATS-IR) with offline meta-learned initialization. LATS-IR performs UCT-guided hierarchical search, first exploring macro-structural pipeline choices and then refining numerical parameters, with natural-language reflections to guide subsequent mutations and provide inspectable search traces. We evaluate IRAH on three in-distribution benchmarks and one out of-distribution benchmark to assess generalization under distribution shift. Under the same meta-learned initialization, LATS-IR outperforms TPE on two of three in-distribution benchmarks, with gains of up to 6.4%, and remains "},{"url":"https://arxiv.org/abs/2610.30379","pdf":"https://arxiv.org/pdf/2610.30379.pdf","id":"arxiv:2610.30379","announceDate":"2026-10-23","tags":["LLM Training","Planning","Hallucination","Fine-tuning"],"source":"arxiv","submittedDate":"2026-10-21","arxiv":"https://arxiv.org/abs/2610.30379","topics":["LLM Training","Planning","Hallucination","Fine-tuning"],"authors":["Tengwei Song","Robert Hoehndorf"],"title":"MemPlan: Memory-Conditioned PDDL Planning for Partially Observable Text Environments","date":"2026-10-23","upvotes":0,"abstract":"LLM agents are flexible in language interaction, but using them as long-horizon planners is costly and prone to hallucinated or invalid actions. This paper targets a different role for LLMs: constrained bridges between language and symbolic planning. We propose MemPlan, a memory-conditioned PDDL planning framework for partially observable interactive text environments. MemPlan keeps the PDDL domain fixed and reconstructs the PDDL problem at each step from parsed observations, candidate hypotheses, and interaction memory. Positive graph memory assigns relevance-based action costs to candidate hypotheses for missing objects, locations, or conditions, guiding the planner toward more plausible checks. Negative memory records execution-refuted assumptions and compiles them into exclusion constraints, preventing repeated attempts at candidates already contradicted by feedback. A unified schema"},{"url":"https://arxiv.org/abs/2610.31467","pdf":"https://arxiv.org/pdf/2610.31467.pdf","id":"arxiv:2610.31467","announceDate":"2026-10-23","tags":["Agentic RAG","Agentic Search","Hallucination","Alignment"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31467","topics":["Agentic RAG","Agentic Search","Hallucination","Alignment"],"authors":["Bayram Ayadi","Florian Geissler","Johanna Schmidhuber"],"title":"From Structured Records to Patient Narratives: Preserving Clinical Alignment in LLM-Generated Health Summaries","date":"2026-10-23","upvotes":0,"abstract":"As wearable and digital health systems increasingly generate longitudinal physiological records, communicating these observations in patient-accessible language remains a significant challenge. Large Language Models (LLMs) offer a promising mechanism for translating structured clinical information into readable narratives, but this process may introduce semantic drift, where clinically precise meaning is distorted during simplification. We investigate evidence-grounded health summarization for menstrual health monitoring using a constrained generation framework that combines structured evidence conditioning with Retrieval-Augmented Generation (RAG) using a prompt-based constrained generation framework. We evaluate semantic alignment using Natural Language Inference (NLI), atomic factuality metrics, and readability measures. Across three LLMs and 4,500 generated summaries, explicit ground"},{"url":"https://arxiv.org/abs/2610.30193","pdf":"https://arxiv.org/pdf/2610.30193.pdf","id":"arxiv:2610.30193","announceDate":"2026-10-23","tags":["Agentic RAG","Agentic Search","Agent Safety","Evaluation"],"source":"arxiv","submittedDate":"2026-10-21","arxiv":"https://arxiv.org/abs/2610.30193","topics":["Agentic RAG","Agentic Search","Agent Safety","Evaluation"],"authors":["Peiyang Liu","Xi Wang","Di Liang","Youru Li","Zhi Cai","Wei Ye"],"title":"Protection Is Not One Event: A Survey of RAG Protection Research by Measured Endpoint","date":"2026-10-23","upvotes":0,"abstract":"Retrieval-augmented generation (RAG) systems face security, privacy, and copyright risks including content leakage, source reconstruction, unauthorized access, data poisoning, and prompt injection. Yet RAG protection studies use incompatible evaluation metrics, datasets, and threat models. We present a systematic survey and human-coded evidence map of 118 full-text-confirmed RAG defense papers, organized by measured endpoint rather than claimed goal or defense mechanism. Our seven-family taxonomy covers content disclosure, formal privacy proxies, access control and suppression, corpus-use detection, and pipeline integrity and attribution. Thirty-two annotators double-coded the papers kappa=0.867. The survey identifies three gaps. First, retrieval reranking and context rewriting each span five or six endpoint families, so mechanisms do not identify protection outcomes. Second, only 17.8% "},{"url":"https://arxiv.org/abs/2610.31117","pdf":"https://arxiv.org/pdf/2610.31117.pdf","id":"arxiv:2610.31117","announceDate":"2026-10-23","tags":["VLM Training","Reasoning","Evaluation","Alignment"],"source":"arxiv","submittedDate":"2026-10-22","arxiv":"https://arxiv.org/abs/2610.31117","topics":["VLM Training","Reasoning","Evaluation","Alignment"],"authors":["Olga Loginova","Oleksandr Bezrukov","Frank Keller"],"title":"Through a PRISM, Clearly: Step-Sequence Reasoning for Mistake Recognition in Procedural Videos","date":"2026-10-23","upvotes":0,"abstract":"Procedural mistake recognition requires identifying deviations from valid multi-step activities. We study post-completion recognition from videos with benchmark-provided step boundaries. We introduce PRISM (Procedural mistake Recognition via Interpretable Semantic Modeling), which grounds video segments in language and maps their descriptions to procedural states using a lightweight hidden Markov model trained on correct executions. Reference alignment and semantic checks identify errors in step content and order. To support evaluation across heterogeneous benchmarks, we map dataset-specific annotations to four edit-based error types: insertion, deletion, substitution, and transposition. Across three benchmarks, we compare gold and VLM-generated descriptions in raw, semantic-role, and action-object forms. Decoder controls show consistent gains from the trained local decoder over nearest-"}],"archive":[],"latestPath":"data/latest.json"};
